package fraymus.workspace;

import java.nio.*;
import java.nio.channels.FileChannel;
import java.nio.file.*;
import java.time.Instant;
import java.util.*;
import org.json.*;

/** Private original screenshots and versioned successful visual-routine associations. */
final class VisualMemory043 {
    private final Path root,index;
    private JSONObject state;
    private final Map<String,Long> sequences=new HashMap<>();
    private final LinkedHashMap<String,JSONObject> cache=new LinkedHashMap<>();
    VisualMemory043(Path project)throws Exception{root=project.resolve("agency-043/screens");index=root.resolve("index.json");Files.createDirectories(root);state=Files.exists(index)?AgentFiles042.loadChecked(index):new JSONObject().put("frames",new JSONArray()).put("patterns",new JSONArray()).put("totalBytes",0);for(Object raw:state.getJSONArray("frames")){var ref=(JSONObject)raw;if(!metadata(ref.getString("id")).getString("sha256").equals(ref.getString("sha256")))throw new IllegalStateException("Visual index differs");original(ref.getString("id"));var source=metadata(ref.getString("id")).getJSONObject("source");sequences.merge(source.getString("sessionId"),source.getLong("sequence"),Math::max);} }
    private void save()throws Exception{AgentFiles042.saveChecked(index,state);}
    private Path path(String id,String suffix){UUID.fromString(id);return root.resolve(id+suffix);}
    synchronized JSONObject metadata(String id)throws Exception{if(cache.containsKey(id))return WorldFrames.copy(cache.get(id));var data=AgentFiles042.loadChecked(path(id,".json"));if(!data.getString("id").equals(id))throw new IllegalStateException("Visual identity differs");cache.put(id,data);while(cache.size()>64)cache.remove(cache.keySet().iterator().next());return WorldFrames.copy(data);}
    synchronized byte[] original(String id)throws Exception{var m=metadata(id);var bytes=Files.readAllBytes(path(id,".png"));if(bytes.length!=m.getInt("bytes")||!PerceptionStore.hash(bytes).equals(m.getString("sha256")))throw new IllegalStateException("Original screen pixels differ; retained for inspection");return bytes;}
    synchronized JSONObject retain(String taskId,String effectId,String sessionId,String phase,JSONObject source,String encoded)throws Exception{
        SpatialScene.keys(source,"kind","sessionId","sequence","elapsedMs","url","title","viewport","artifactId","artifactVersion","testIndex");
        if(!Set.of("browser","canvas","workspace").contains(source.getString("kind"))||!sessionId.equals(source.getString("sessionId"))||source.getLong("sequence")<1||source.getDouble("sequence")!=source.getLong("sequence")||source.getDouble("elapsedMs")<0||!Double.isFinite(source.getDouble("elapsedMs")))throw new IllegalArgumentException("Source session/sequence/clock invalid");
        if(source.getString("url").length()>2048||source.getString("title").length()>240||!(source.getString("url").matches("https?://.*")||source.getString("kind").equals("workspace")&&source.getString("url").startsWith("file:")&&source.getString("url").endsWith("/renderer/index.html")))throw new IllegalArgumentException("Bounded actual web surface required");
        if(source.getLong("sequence")<=sequences.getOrDefault(sessionId,0L))throw new IllegalArgumentException("Stale screenshot sequence; original retained");
        if(encoded.length()>8_000_000)throw new IllegalArgumentException("Screen byte budget exceeded");var bytes=Base64.getDecoder().decode(encoded);var image=ScreenPixels043.decode(bytes);var viewport=source.getJSONArray("viewport");if(viewport.length()!=2||viewport.getInt(0)!=image.getWidth()||viewport.getInt(1)!=image.getHeight())throw new IllegalArgumentException("Screen source dimensions differ");
        if(state.getJSONArray("frames").length()>=1024||state.getLong("totalBytes")+bytes.length>256_000_000)throw new IllegalStateException("Visual retention budget reached; archive deliberately before more captures");
        String id=UUID.randomUUID().toString();var meta=new JSONObject().put("id",id).put("taskId",taskId).put("effectId",effectId).put("phase",phase).put("source",WorldFrames.copy(source)).put("sha256",PerceptionStore.hash(bytes)).put("bytes",bytes.length).put("receivedAt",Instant.now().toString()).put("signature",ScreenPixels043.signature(image));
        try(var channel=FileChannel.open(path(id,".png"),StandardOpenOption.CREATE_NEW,StandardOpenOption.WRITE)){var b=ByteBuffer.wrap(bytes);while(b.hasRemaining())channel.write(b);channel.force(true);}
        AgentFiles042.saveChecked(path(id,".json"),meta);state.getJSONArray("frames").put(new JSONObject().put("id",id).put("sha256",meta.getString("sha256")));state.put("totalBytes",state.getLong("totalBytes")+bytes.length);save();sequences.put(sessionId,source.getLong("sequence"));cache.put(id,meta);return brief(meta);
    }
    static JSONObject brief(JSONObject frame){var out=WorldFrames.copy(frame);out.remove("signature");return out.put("visual",new JSONObject().put("dimensions",frame.getJSONObject("signature").getInt("dimensions")).put("contrast",frame.getJSONObject("signature").getDouble("contrast")).put("informative",frame.getJSONObject("signature").getBoolean("informative")));}
    synchronized JSONObject pair(String beforeId,String afterId)throws Exception{var a=metadata(beforeId);var b=metadata(afterId);var x=a.getJSONObject("source");var y=b.getJSONObject("source");if(!a.getString("taskId").equals(b.getString("taskId"))||!a.getString("effectId").equals(b.getString("effectId"))||!a.getString("phase").equals("before")||!b.getString("phase").equals("after")||!x.getString("sessionId").equals(y.getString("sessionId"))||!x.getString("kind").equals(y.getString("kind"))||x.getLong("sequence")>=y.getLong("sequence")||x.getDouble("elapsedMs")>y.getDouble("elapsedMs"))throw new IllegalStateException("Screen pair crosses action/session/source order");return ScreenPixels043.difference(ScreenPixels043.decode(original(beforeId)),ScreenPixels043.decode(original(afterId))).put("beforeId",beforeId).put("afterId",afterId).put("beforeSha256",a.getString("sha256")).put("afterSha256",b.getString("sha256"));}
    synchronized JSONArray matches(String frameId)throws Exception{var frame=metadata(frameId);var result=new ArrayList<JSONObject>();if(!frame.getJSONObject("signature").getBoolean("informative"))return new JSONArray();for(Object raw:state.getJSONArray("patterns")){var p=(JSONObject)raw;original(p.getString("frameId"));var reference=metadata(p.getString("frameId"));if(!reference.getJSONObject("source").getString("kind").equals(frame.getJSONObject("source").getString("kind")))continue;double score=ScreenPixels043.similarity(reference.getJSONObject("signature"),frame.getJSONObject("signature"));result.add(WorldFrames.copy(p).put("similarity",score).put("meaning","Appearance similarity to a previously tested routine; not a calibrated confidence or action permission"));}result.sort(Comparator.comparingDouble((JSONObject p)->p.getDouble("similarity")).reversed());return new JSONArray(result.subList(0,Math.min(3,result.size())));}
    synchronized JSONObject learn(String taskId,String frameId,JSONObject artifact,JSONObject recipe,JSONArray sequence)throws Exception{
        var test=artifact.optJSONObject("test");if(test==null||!test.optBoolean("passed")||test.getInt("version")!=artifact.getInt("version")||test.getJSONArray("checks").isEmpty())throw new IllegalStateException("Visual routine needs current actual DOM verification");
        var frame=metadata(frameId);if(!frame.getString("taskId").equals(taskId)||!frame.getString("phase").equals("after")||!frame.getJSONObject("source").optString("artifactId").equals(artifact.getString("id"))||frame.getJSONObject("source").optInt("artifactVersion")!=artifact.getInt("version"))throw new IllegalStateException("Visual routine image refers to another artifact/version");original(frameId);
        long prior=-1;for(Object id:sequence){var m=metadata(id.toString());var src=m.getJSONObject("source");if(!m.getString("taskId").equals(taskId)||!m.getString("phase").equals("during")||!src.optString("artifactId").equals(artifact.getString("id"))||src.optInt("artifactVersion")!=artifact.getInt("version")||src.getLong("sequence")<=prior)throw new IllegalStateException("Visual routine sequence crosses source/version/order");prior=src.getLong("sequence");original(id.toString());}
        for(Object raw:state.getJSONArray("patterns"))if(((JSONObject)raw).getString("taskId").equals(taskId))return WorldFrames.copy((JSONObject)raw);
        if(state.getJSONArray("patterns").length()>=64)throw new IllegalStateException("Visual routine budget64 reached");
        var p=new JSONObject().put("id",UUID.randomUUID().toString()).put("taskId",taskId).put("frameId",frameId).put("imageSha256",frame.getString("sha256")).put("artifactId",artifact.getString("id")).put("artifactVersion",artifact.getInt("version")).put("testSha256",WorldFrames.hash(test)).put("sequence",new JSONArray(sequence.toString())).put("recipe",recipe==null?JSONObject.NULL:recipe).put("createdAt",Instant.now().toString()).put("kind","tested-visual-routine-reference");state.getJSONArray("patterns").put(p);save();return WorldFrames.copy(p);
    }
    synchronized JSONObject state(){return new JSONObject().put("frames",state.getJSONArray("frames").length()).put("bytes",state.getLong("totalBytes")).put("patterns",WorldFrames.copy(new JSONObject().put("v",state.getJSONArray("patterns"))).getJSONArray("v")).put("scope","Private original screenshots and tested appearance references. No semantic identity, calibrated certainty or model-weight training.");}
    synchronized String thumbnail(String id,int maximum)throws Exception{return Base64.getEncoder().encodeToString(ScreenPixels043.thumbnail(ScreenPixels043.decode(original(id)),maximum));}
}
